1:
    beqz a4, 2f
    lbu t1, 0(a2)
    lbu t2, 0(a3)
    bne t1, t2, 3f
    addi a2, a2, 1
    addi a3, a3, 1
    addi a4, a4, -1
    j 1b
2:
    ret
3:
    mv a0, s10
    j fail

